-- =============================================================================
-- table_select.sql
-- 테이블 + 컬럼 + 인덱스 + 제약조건 캐시 (조회 전용)
-- DBMS: Oracle 21c XE
-- 메타뷰: USER_TAB_COMMENTS / USER_TAB_COLUMNS / USER_INDEXES / USER_CONSTRAINTS
-- 출력 형식: 파이프(`|`) 구분. 사람 + Claude 둘 다 빠르게 grep 가능.
-- =============================================================================

ALTER SESSION SET CURRENT_SCHEMA = rental;

SET PAGESIZE 0
SET LINESIZE 500
SET FEEDBACK OFF
SET HEADING OFF
SET TRIMSPOOL ON
SET ECHO OFF
SET VERIFY OFF
WHENEVER SQLERROR EXIT FAILURE

PROMPT === TABLES ===
PROMPT TABLE_NAME|COMMENTS
SELECT TABLE_NAME || '|' || NVL(COMMENTS, '')
  FROM USER_TAB_COMMENTS
 WHERE TABLE_TYPE = 'TABLE'
   AND TABLE_NAME NOT LIKE 'BIN$%'
 ORDER BY TABLE_NAME;

PROMPT
PROMPT === COLUMNS ===
PROMPT TABLE_NAME|COLUMN_NAME|DATA_TYPE|DATA_LENGTH|NULLABLE
SELECT TABLE_NAME || '|'
       || COLUMN_NAME || '|'
       || DATA_TYPE || '|'
       || NVL(TO_CHAR(DATA_LENGTH), '') || '|'
       || NULLABLE
  FROM USER_TAB_COLUMNS
 WHERE TABLE_NAME NOT LIKE 'BIN$%'
 ORDER BY TABLE_NAME, COLUMN_ID;

PROMPT
PROMPT === CONSTRAINTS ===
PROMPT TABLE_NAME|CONSTRAINT_NAME|TYPE|COLUMNS|REFERENCES
SELECT c.TABLE_NAME || '|'
       || c.CONSTRAINT_NAME || '|'
       || CASE c.CONSTRAINT_TYPE
              WHEN 'P' THEN 'PK'
              WHEN 'U' THEN 'UNIQUE'
              WHEN 'R' THEN 'FK'
              WHEN 'C' THEN 'CHECK'
          END || '|'
       || (SELECT LISTAGG(cc.COLUMN_NAME, ',') WITHIN GROUP (ORDER BY cc.POSITION)
             FROM USER_CONS_COLUMNS cc
            WHERE cc.CONSTRAINT_NAME = c.CONSTRAINT_NAME) || '|'
       || NVL(c.R_CONSTRAINT_NAME, '')
  FROM USER_CONSTRAINTS c
 WHERE c.CONSTRAINT_TYPE IN ('P', 'U', 'R')
   AND c.TABLE_NAME NOT LIKE 'BIN$%'
 ORDER BY c.TABLE_NAME, c.CONSTRAINT_TYPE, c.CONSTRAINT_NAME;

PROMPT
PROMPT === INDEXES ===
PROMPT TABLE_NAME|INDEX_NAME|UNIQUENESS|COLUMNS
SELECT i.TABLE_NAME || '|'
       || i.INDEX_NAME || '|'
       || i.UNIQUENESS || '|'
       || (SELECT LISTAGG(ic.COLUMN_NAME || CASE ic.DESCEND WHEN 'DESC' THEN ' DESC' ELSE '' END, ',')
                  WITHIN GROUP (ORDER BY ic.COLUMN_POSITION)
             FROM USER_IND_COLUMNS ic
            WHERE ic.INDEX_NAME = i.INDEX_NAME)
  FROM USER_INDEXES i
 WHERE i.TABLE_NAME NOT LIKE 'BIN$%'
   AND i.INDEX_TYPE = 'NORMAL'
 ORDER BY i.TABLE_NAME, i.INDEX_NAME;

PROMPT
PROMPT === SEQUENCES ===
PROMPT SEQUENCE_NAME|LAST_NUMBER|INCREMENT_BY
SELECT SEQUENCE_NAME || '|' || LAST_NUMBER || '|' || INCREMENT_BY
  FROM USER_SEQUENCES
 ORDER BY SEQUENCE_NAME;

EXIT;
